    return Sequence(
        Fallback(
            Leaf("bowl_on_stove_check"),
            Sequence(
                Leaf("approach_bowl"),
                Leaf("pick_bowl"),
                Leaf("place_bowl_on_stove"),
                Leaf("open_gripper"),
                Leaf("retreat"),
            ),
        ),
        Fallback(
            Leaf("stove_on_check"),
            Leaf("turn_on_stove"),
